/** 字符工具 **/
import { MATCH } from "./regexp";

/**
 * @name 脱敏手机
 * @param {string} [phone=""] 手机
 */
function desePhone(phone = ""): string {
	return MATCH.phone.regexp.test(phone)
		? phone.replace(/(\d{3})\d*(\d{4})/, "$1****$2")
		: phone;
}

/**
 * @name 格式手机
 * @param {string} [phone=""] 手机
 * @param {string} [sign="-"] 标记：-、\s
 */
function formatPhone(phone = "", sign: "-" | " " = "-"): string {
	return MATCH.phone.regexp.test(phone) && ["-", " "].includes(sign)
		? phone.replace(/(\d{3})(\d{4})(\d{4})/, `$1${sign}$2${sign}$3`)
		: phone;
}

/**
 * @name 随机HEX色值
 */
function randomColor(): string {
	return `#${Math.floor(Math.random() * 0xffffff).toString(16)
		.padEnd(6, "0")}`;
}

/**
 * @name 随机长度ID
 * @param {number} [len=5] 长度 在1~10之间
 */
function randomId(len = 5): string {
	const finalLen = Math.min(10, Math.max(1, len));
	return Math.random().toString(36)
		.slice(2, finalLen + 2);
}

/**
 * @name 删除标签
 * @param {string} [html=""] HTML
 */
function removeTag(html = ""): string {
	return html.replace(/<[^>]*>/g, "");
}

/**
 * @name 翻转文本
 * @param {string} [text=""] 文本
 */
function reverseText(text = ""): string {
	return text.split("").reverse()
		.join("");
}

/**
 * @name 星级评分
 * @param {number} [rate=0] 星级 在0~len之间
 * @param {number} [len=5] 长度
 */
function startScore(rate = 0, len = 5): string {
	const finalRate = Math.min(len, Math.max(0, rate));
	return "★".repeat(finalRate) + "☆".repeat(len - finalRate);
}

export {
	desePhone,
	formatPhone,
	randomColor,
	randomId,
	removeTag,
	reverseText,
	startScore
};