/** 正则工具 **/
type FieldEnum = "address" | "count" | "date" | "email" | "idcard" | "image" | "name" | "number" | "password" | "phone";

interface CheckType {
	flag: boolean
	msg: string
}

const MATCH: Record<FieldEnum, {
	msg: string
	regexp: RegExp
}> = {
	address: {
		msg: "地址只能由2~200位中文、英文、数字或空格组成",
		regexp: /^[\u4e00-\u9fa5A-Za-z0-9 ]{2,200}$/
	},
	count: {
		msg: "数量只能由数字组成",
		regexp: /^\d{1,}$/
	},
	date: {
		msg: "日期只能由YYYY-MM-DD HH:mm:ss形式组成",
		regexp: /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/
	},
	email: {
		msg: "邮箱只能由xxx@yyy.zzz形式组成",
		regexp: /\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*/
	},
	idcard: {
		msg: "身份证只能由13位数字或12位数字和X组成",
		regexp: /^(^[1-9]\d{7}((0\d)|(1[0-2]))(([0|1|2]\d)|3[0-1])\d{3}$)|(^[1-9]\d{5}[1-9]\d{3}((0\d)|(1[0-2]))(([0|1|2]\d)|3[0-1])((\d{4})|\d{3}[Xx])$)$/
	},
	image: {
		msg: "图像只能是JPG、PNG、GIF、SVG或WEBP类型",
		regexp: /\.(jpe?g|png|gif|svg|webp)$/i
	},
	name: {
		msg: "名称只能由2~50位中文、英文、数字、下划线或中划线组成",
		regexp: /^[\u4e00-\u9fa5\w-]{2,50}$/
	},
	number: {
		msg: "计数只能由数字或小数点组成",
		regexp: /^[+-]?(0|([1-9]\d*))(\.\d+)?$/
	},
	password: {
		msg: "密码只能由8~20位英文、数字或符号至少两种组成",
		regexp: /^(?![0-9]+$)(?![a-z]+$)(?![A-Z]+$)(?!([^(0-9a-zA-Z)])+$)^.{8,20}$/
	},
	phone: {
		msg: "手机只能由11位数字组成且符合通讯运营商规范",
		regexp: /^1\d{10}$/
	}
};

const SIGN = "^$.*+-?=!:|\\/()[]{}".split("");

/**
 * @name 校验文本
 * @param {string} [type=""] 类型：address、count、date、email、idcard、image、name、number、password、phone
 * @param {string} [text=""] 文本
 */
function checkText(type: FieldEnum = "phone", text = ""): CheckType {
	const { msg, regexp } = MATCH[type];
	const flag = regexp.test(text);
	return { flag, msg: flag ? "" : msg };
}

/**
 * @name 自定义校验文本
 * @param {regexp} [regexp] 正则
 * @param {string} [text=""] 文本
 * @param {string} [msg=""] 提示
 */
function checkTextPlus(regexp: RegExp, text = "", msg = ""): CheckType {
	const flag = regexp.test(text);
	return { flag, msg: flag ? "" : msg };
}

/**
 * @name 匹配括号文本
 * @param {string} [tgt="(*)"] 括号形式(提取的内容必须使用*代替)
 * @param {string} [text=""] 文本
 */
function matchBracketText(tgt = "(*)", text = ""): string[] {
	const bracket = tgt.split("*").map(v => `${SIGN.includes(v) ? "\\" : ""}${v}`);
	const regexp = new RegExp(`${bracket[0]}(.+?)${bracket[1]}`, "g");
	const match = text.match(regexp) ?? [];
	return match.map(v => v.replace(regexp, "$1"));
}

export {
	MATCH,
	checkText,
	checkTextPlus,
	matchBracketText
};